/* MainLayout 模組樣式 */

.mainLayout {
  display: flex;
  flex-direction: column;
  background-color: var(--bg-main);
}

.header {
  background-color: var(--bg-header);
  border-bottom: 2px solid var(--tiffany-dark);
  box-shadow: var(--shadow-md);
  flex-shrink: 0;
  position: sticky; /* Make search bar sticky */
  top: 0;
  z-index: 1000;
}

/* Three-Column Container */
.container {
  display: grid;
  grid-template-columns: 300px 1fr 350px;
  gap: 0;
}

.leftColumn,
.centerColumn,
.rightColumn {
  display: flex;
  flex-direction: column;
  min-height: 0;
  min-width: 0;
}

.leftColumn {
  background-color: var(--bg-card-light);
  border-right: 1px solid var(--border-color);
}

.centerColumn {
  background-color: var(--bg-main);
}

.rightColumn {
  background-color: var(--bg-card-light);
  border-left: 1px solid var(--border-color);
}

/* Right Panel Wrapper */
.rightPanelWrapper {
  display: flex;
  flex-direction: column;
  height: 100%;
  overflow: hidden;
}

.panelHeader {
  padding: 1rem;
  border-bottom: 1px solid var(--border-color);
  background-color: var(--bg-card);
  flex-shrink: 0;
}

.panelTitle {
  margin: 0;
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--text-primary);
}

.panelContent {
  flex: 1;
  overflow-y: auto;
  padding: 1rem;
  display: flex;
  flex-direction: column;
}

/* 響應式設計 - 平板 */
@media (max-width: 1200px) {
  .container {
    grid-template-columns: 280px 1fr 300px;
  }
}

@media (max-width: 1024px) {
  .container {
    grid-template-columns: 1fr 1fr;
  }

  .leftColumn {
    border-right: 1px solid var(--border-color);
    border-bottom: 1px solid var(--border-color);
  }

  .rightColumn {
    grid-column: 1 / -1;
    border-left: none;
    border-top: 1px solid var(--border-color);
    max-height: 300px;
  }
}

/* 響應式設計 - 手機 */
@media (max-width: 768px) {
  .mainLayout {
    height: auto;
  }

  .container {
    grid-template-columns: 1fr;
    height: auto;
  }

  .leftColumn,
  .centerColumn,
  .rightColumn {
    min-height: 400px;
    max-height: none;
  }

  .leftColumn {
    border-right: none;
    border-bottom: 1px solid var(--border-color);
  }

  .centerColumn {
    border-bottom: 1px solid var(--border-color);
  }

  .rightColumn {
    border-left: none;
    border-top: 1px solid var(--border-color);
  }
}

/* Scrollbar Styling */
.container > * {
  scrollbar-width: thin;
  scrollbar-color: var(--border-color) var(--bg-main);
}

.container > *::-webkit-scrollbar {
  width: 8px;
}

.container > *::-webkit-scrollbar-track {
  background: var(--bg-main);
}

.container > *::-webkit-scrollbar-thumb {
  background: var(--border-color);
  border-radius: 4px;
}

.container > *::-webkit-scrollbar-thumb:hover {
  background: var(--border-dark);
}

/**
 * LeftPanel Component
 * Displays trend analysis and journal statistics
 */
import React, { useContext } from 'react';
import { LineChart, Line, BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import { SearchContext } from '../../context/SearchContext.jsx';
import styles from './LeftPanel.module.css';

export function LeftPanel() {
  const { trendData, journalData } = useContext(SearchContext);

  return (
    <div className={styles.leftPanel}>
      <div className={styles.panelHeader}>
        <h2 className={styles.panelTitle}>📊 Analytics</h2>
      </div>

      <div className={styles.panelContent}>
        {/* Trend Chart */}
        {trendData && trendData.length > 0 && (
          <div className={styles.chartContainer}>
            <h3 className={styles.chartTitle}>Publication Trend</h3>
            <ResponsiveContainer width="100%" height={250}>
              <LineChart data={trendData}>
                <CartesianGrid strokeDasharray="3 3" stroke="var(--border-color)" />
                <XAxis dataKey="year" stroke="var(--text-secondary)" />
                <YAxis stroke="var(--text-secondary)" />
                <Tooltip
                  contentStyle={{
                    backgroundColor: 'var(--bg-card)',
                    border: `1px solid var(--border-color)`,
                    borderRadius: '4px',
                  }}
                  labelStyle={{ color: 'var(--text-primary)' }}
                />
                <Legend wrapperStyle={{ color: 'var(--text-secondary)' }} />
                <Line
                  type="monotone"
                  dataKey="count"
                  stroke="var(--coral-primary)"
                  strokeWidth={2}
                  dot={{ fill: 'var(--coral-primary)', r: 4 }}
                  activeDot={{ r: 6 }}
                />
              </LineChart>
            </ResponsiveContainer>
          </div>
        )}

        {/* Journal Chart */}
        {journalData && journalData.length > 0 && (
          <div className={styles.chartContainer}>
            <h3 className={styles.chartTitle}>Top Journals</h3>
            <ResponsiveContainer width="100%" height={250}>
              <BarChart
                data={journalData}
                layout="vertical"
                margin={{ top: 5, right: 30, left: 150, bottom: 5 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="var(--border-color)" />
                <XAxis type="number" stroke="var(--text-secondary)" />
                <YAxis
                  dataKey="journal"
                  type="category"
                  stroke="var(--text-secondary)"
                  width={140}
                  tick={{ fontSize: 11 }}
                />
                <Tooltip
                  contentStyle={{
                    backgroundColor: 'var(--bg-card)',
                    border: `1px solid var(--border-color)`,
                    borderRadius: '4px',
                  }}
                  labelStyle={{ color: 'var(--text-primary)' }}
                />
                <Bar dataKey="count" fill="var(--tiffany-primary)" radius={[0, 4, 4, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        )}

        {!trendData && !journalData && (
          <div className={styles.emptyState}>
            <p>📭 No data yet</p>
            <p style={{ fontSize: '0.9rem' }}>Search for a term to see analytics</p>
          </div>
        )}
      </div>
    </div>
  );
}

/* LeftPanel 模組樣式 */

.leftPanel {
  display: flex;
  flex-direction: column;
  background-color: var(--bg-main);
  border-right: 1px solid var(--border-color);
}

.panelHeader {
  padding: 1rem;
  border-bottom: 1px solid var(--border-color);
  background-color: var(--bg-card);
}

.panelTitle {
  margin: 0;
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--text-primary);
}

.panelContent {
  padding: 1rem;
  display: flex;
  flex-direction: column;
  gap: 2rem;
}

/* Chart Container */
.chartContainer {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 4px;
  padding: 1rem;
}

.chartTitle {
  margin: 0 0 0.5rem 0;
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-primary);
}

/* Empty State */
.emptyState {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100%;
  color: var(--text-secondary);
  text-align: center;
}

.emptyState p {
  margin: 0.5rem 0;
  font-size: 1rem;
}

.emptyState p:first-child {
  font-size: 2rem;
}

/* 響應式設計 */
@media (max-width: 1024px) {
  .panelContent {
    padding: 0.75rem;
  }

  .chartContainer {
    padding: 0.75rem;
  }
}

@media (max-width: 768px) {
  .leftPanel {
    border-right: none;
  }

  .panelContent {
    gap: 1rem;
  }
}

