response.output:
/* SearchBar Module - Final Polish */

.searchContainer {
  display: flex;
  gap: 1.5rem; /* Tighter gap */
  padding: 0.25rem 0.5rem;
  background-color: var(--bg-header);
  align-items: center; /* Vertically align logo and search controls */
}

/* Left Column: Logo */
.logoWrapper {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 0.5rem;
  flex-shrink: 0;
}

.logoImage {
  height: 120px;
  width: 120px;
  object-fit: contain;
}

.logoTextWrapper {
  display: flex;
  flex-direction: column;
  justify-content: center; /* Center content vertically */
  gap: 0.2rem; /* Small gap between title and subtitle */
}

.logoTitle {
  font-size: 2rem;
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1.1;
  margin: 0; /* Remove default h1 margin */
}

.logoSubtitle {
  font-size: 0.7rem;
  font-weight: 500;
  color: var(--text-secondary);
  max-width: 180px;
  margin: 0; /* Remove default p margin */
}

/* Right Column: Search Controls */
.searchControls {
  display: flex;
  flex-direction: column;
  gap: 0;
  flex-grow: 1;
  position: relative;
  min-width: 0;
  min-height: 125px;
}

.controlsTopRow {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 0.75rem;
  flex: 1; /* Occupy top half space */
}

.operatorGroup {
  display: flex;
  gap: 0.25rem; /* Tighter buttons */
}

.operatorButton {
  padding: 0.2rem 0.6rem;
  background: var(--coral-primary);
  border: none;
  border-radius: 4px;
  font-size: 0.75rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s ease;
  color: white;
  position: relative; /* For hover indicator */
}

.operatorButton:hover,
.operatorButton.focused {
  background: var(--coral-dark);
  box-shadow: 0 0 0 2px var(--coral-light);
  color: black;
}

.operatorButton.active {
  background: var(--coral-dark);
  box-shadow: 0 0 0 2px var(--coral-light);
}

.operatorButton::before {
  content: '▼';
  position: absolute;
  top: 110%;
  left: 50%;
  transform: translateX(-50%);
  opacity: 0;
  transition: all 0.2s ease;
  color: var(--coral-dark);
  font-size: 0.8rem;
  pointer-events: none;
  z-index: 10;
}

.operatorButton:hover::before,
.operatorButton.focused::before {
  opacity: 1;
  top: 130%;
}

.clearButton {
  position: absolute;
  right: 0.8rem;
  top: 50%;
  transform: translateY(-50%);
  background: none;
  border: none;
  font-size: 1.5rem;
  color: var(--text-secondary);
  cursor: pointer;
  padding: 0;
  line-height: 1;
}
.clearButton:hover {
  color: var(--text-primary);
}

/* Search Input Container - relative positioning for autocomplete popup */
.searchInputContainer {
  position: relative;
  display: flex;
  flex-direction: column;
  width: 100%;
}

.searchInputWrapper {
  display: flex;
  position: relative;
  width: 100%;
}

.searchInput {
  width: 100%;
  padding: 0.6rem 2.5rem 0.6rem 1rem;
  font-size: 0.95rem;
  border: 1px solid var(--border-light);
  border-radius: 4px;
  background: white;
  transition: all 0.2s ease;
}

.searchInput:focus {
  border-color: var(--tiffany-primary);
  box-shadow: 0 0 0 3px rgba(64, 224, 208, 0.2);
}

/* Related Terms Tags */
.relatedTagsContainer {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  overflow-x: auto; /* Use horizontal scrolling */
  overflow-y: visible; /* Allow triangle indicator to show */
  flex-wrap: nowrap;   /* Use horizontal scrolling */
  padding: 6px 0;
  scrollbar-width: thin;
  position: relative;
  z-index: 10; /* Below search input */
  flex: 1; /* Occupy bottom half space */
}

.relatedTagsLabel {
  font-size: 0.85rem;
  font-weight: 500;
  color: var(--text-secondary);
  flex-shrink: 0;
  white-space: nowrap;
}

.relatedTag {
  padding: 0.25rem 0.7rem;
  background-color: #E0F2F1; /* Light teal background */
  color: #00796B; /* Dark teal text */
  border: 1px solid #B2DFDB; /* Teal border */
  border-radius: 16px;
  font-size: 0.8rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s ease;
  flex-shrink: 0;
  position: relative; /* For hover indicator */
}

.relatedTag:hover,
.relatedTag.focused {
  background-color: #B2DFDB;
  box-shadow: 0 0 0 2px var(--tag-success-light);
  color: black;
}

.relatedTag::before {
  content: '▲';
  position: absolute;
  bottom: 120%;
  left: 50%;
  transform: translateX(-50%);
  opacity: 0;
  transition: all 0.2s ease;
  color: var(--tag-success-dark);
  font-size: 0.8rem;
  pointer-events: none;
  z-index: 10;
}

.relatedTag:hover::before,
.relatedTag.focused::before {
  opacity: 1;
  bottom: 140%;
}

/* Autocomplete Popup */
.autocompletePopup {
  position: absolute;
  top: calc(100% - 1px); /* Align top border with input bottom border */
  left: 0;
  right: 0;
  width: 100%;
  z-index: 30; /* Highest z-index */
  background: white;
  border: 1px solid var(--border-light);
  border-top: none;
  margin: 0;
  padding: 0;
}

.suggestionsList {
  list-style: none;
  margin: 0;
  padding: 0.25rem 0;
  max-height: 300px;
  overflow-y: auto;
}

.suggestionItem {
  padding: 0.6rem 1rem;
  cursor: pointer;
  font-size: 0.9rem;
}

.suggestionItem:hover {
  background: var(--bg-card);
}

.suggestionItem.focused {
  background: var(--coral-primary);
  color: white;
}

.suggestionText strong {
  font-weight: 600;
  color: inherit;
}

