}

.paginationBtn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.paginationBtn.active {
  background-color: var(--coral-primary);
  border-color: var(--coral-primary);
  color: var(--text-on-accent);
}

.paginationEllipsis {
  padding: 0.5rem 0.25rem;
  color: var(--text-secondary);
}

.pageInfo {
  font-size: 0.9rem;
  color: var(--text-secondary);
  margin: 0 0.5rem;
  white-space: nowrap;
}

